fn is_qty(t: Str) -> Bool {
  if t.is_empty() {
    return false
  }
  let digits = t.chars().all(fn(c) => "0123456789".contains(c))
  if not digits {
    return false
  }
  return t.to_int().unwrap_or(0) > 0
}

pub fn inventory(orders: List[Str], stock: Map[Str, Int]) -> Result[List[Str], Str] {
  var inv: Map[Str, Int] = stock
  var filled: List[Str] = []
  for order in orders {
    let parts = order.split(" ")
    let id = parts.get_or(0, "")
    if parts.len() != 2 or id == "" {
      return Err("bad order " + id)
    }
    var need: Map[Str, Int] = Map {}
    let lines = parts.get_or(1, "").split(",")
    for line in lines {
      let kv = line.split(":")
      if kv.len() != 2 {
        return Err("bad order " + id)
      }
      let item = kv.get_or(0, "")
      let qtxt = kv.get_or(1, "")
      if item == "" or not is_qty(qtxt) or not inv.has(item) {
        return Err("bad order " + id)
      }
      let q = qtxt.to_int().unwrap_or(0)
      need = need.update(item, 0, fn(x) => x + q)
    }
    var can = true
    for e in need.entries() {
      if inv.get(e.key).unwrap_or(0) < e.value {
        can = false
      }
    }
    if can {
      for e in need.entries() {
        inv = inv.set(e.key, inv.get(e.key).unwrap_or(0) - e.value)
      }
      filled = filled.push(id)
    }
  }
  return Ok(filled)
}
